<?php
declare(strict_types=1);
final class Spreadsheets {
 private const NS='http://schemas.openxmlformats.org/spreadsheetml/2006/main';
 public static function read(string $path,string $name):array {
  if(!is_file($path)||filesize($path)>10485760)throw new InvalidArgumentException('Envie um arquivo de até 10 MB.');
  $ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));if($ext==='csv')return self::csv($path);if($ext!=='xlsx')throw new InvalidArgumentException('Use Excel .xlsx ou CSV UTF-8.');
  if(!class_exists('ZipArchive'))throw new RuntimeException('A hospedagem precisa da extensão ZIP para arquivos Excel. CSV continua disponível.');
  $zip=new ZipArchive();if($zip->open($path)!==true)throw new InvalidArgumentException('O arquivo Excel está inválido.');
  try{$total=0;if($zip->numFiles>2000)throw new InvalidArgumentException('Arquivo Excel com entradas demais.');for($i=0;$i<$zip->numFiles;$i++){$stat=$zip->statIndex($i);$total+=$stat['size'];if($total>67108864)throw new InvalidArgumentException('Arquivo Excel expandido maior que 64 MB.');}
   $xml=static function(string $entry)use($zip):SimpleXMLElement{$text=$zip->getFromName($entry);if($text===false||strlen($text)>33554432||preg_match('/<!DOCTYPE|<!ENTITY/i',$text))throw new InvalidArgumentException('Estrutura Excel não suportada.');$old=libxml_use_internal_errors(true);try{$node=simplexml_load_string($text,SimpleXMLElement::class,LIBXML_NONET|LIBXML_COMPACT);if(!$node)throw new InvalidArgumentException('Planilha com XML inválido.');return $node;}finally{libxml_clear_errors();libxml_use_internal_errors($old);}};
   $strings=[];if($zip->locateName('xl/sharedStrings.xml')!==false){$root=$xml('xl/sharedStrings.xml');$root->registerXPathNamespace('s',self::NS);foreach($root->xpath('//s:si') as $item){$item->registerXPathNamespace('s',self::NS);$text='';foreach($item->xpath('.//s:t') as $t)$text.=(string)$t;$strings[]=$text;}}
   $book=$xml('xl/workbook.xml');$book->registerXPathNamespace('s',self::NS);$rels=[];foreach($xml('xl/_rels/workbook.xml.rels')->children('http://schemas.openxmlformats.org/package/2006/relationships') as $rel){$rel=$rel->attributes();if((string)$rel['TargetMode']==='External')continue;$target=(string)$rel['Target'];$rels[(string)$rel['Id']]=str_starts_with($target,'/')?ltrim($target,'/'):'xl/'.$target;}
   $date1904=(string)($book->workbookPr['date1904']??'')==='1';$sheets=[];
   foreach($book->xpath('//s:sheets/s:sheet') as $sheet){$attrs=$sheet->attributes('http://schemas.openxmlformats.org/officeDocument/2006/relationships');$target=$rels[(string)$attrs['id']]??'';if(!preg_match('~^xl/worksheets/[a-zA-Z0-9_.-]+\.xml$~D',$target))continue;$root=$xml($target);$root->registerXPathNamespace('s',self::NS);$rows=[];
    foreach($root->xpath('//s:sheetData/s:row') as $row){if(count($rows)>=20000)throw new InvalidArgumentException('Use planilhas com até 20.000 linhas por aba.');$values=[];foreach($row->c as $cell){$ref=(string)$cell['r'];preg_match('/^([A-Z]+)/',$ref,$m);$col=0;foreach(str_split($m[1]??'A') as $letter)$col=$col*26+ord($letter)-64;$index=$col-1;if($index>39)continue;$type=(string)$cell['t'];$v=(string)$cell->v;if($type==='s')$v=$strings[(int)$v]??'';elseif($type==='inlineStr'){$cell->registerXPathNamespace('s',self::NS);$v=implode('',array_map('strval',$cell->xpath('.//s:t')));}$values[$index]=trim($v);}$rows[]=['line'=>(int)$row['r'],'values'=>$values];}
    if($rows)$sheets[]=['name'=>(string)$sheet['name'],'rows'=>$rows,'excel'=>true,'date1904'=>$date1904];
   }return self::map($sheets);
  }finally{$zip->close();}
 }
 private static function csv(string $path):array {
  $stream=fopen($path,'rb');if(!$stream)throw new InvalidArgumentException('Não foi possível ler o CSV.');try{$first=fgets($stream);rewind($stream);$sep=substr_count((string)$first,';')>=substr_count((string)$first,',')?';':',';$rows=[];$line=0;while(($values=fgetcsv($stream,0,$sep))!==false){$line++;if($line>20001)throw new InvalidArgumentException('Use CSV com até 20.000 registros.');foreach($values as &$value){$value=preg_replace('/^\xEF\xBB\xBF/','',(string)$value);if(!mb_check_encoding($value,'UTF-8'))$value=mb_convert_encoding($value,'UTF-8','Windows-1252');}unset($value);$rows[]=['line'=>$line,'values'=>$values];}return self::map([['name'=>'CSV','rows'=>$rows,'excel'=>false]]);}finally{fclose($stream);}
 }
 private static function map(array $sheets):array {
  $aliases=[];foreach(Records::LABELS as $i=>$label)$aliases[self::header($label)]=Records::FIELDS[$i];foreach(['veiculo'=>'veiculo','veiculo marca modelo'=>'veiculo','associado vitima'=>'vitima','vitima'=>'vitima','municipio'=>'municipio','data evento'=>'data_evento','id do sistema'=>'system_id','id'=>'system_id','etapa'=>'etapa','observacoes'=>'observacoes'] as $label=>$field)$aliases[$label]=$field;
  $output=[];$issues=[];
  foreach($sheets as $sheet){$map=null;foreach($sheet['rows'] as $row){$values=$row['values'];if(!array_filter($values,static fn($v)=>trim((string)$v)!==''))continue;
    if($map===null){$candidate=[];foreach($values as $col=>$value){$key=self::header((string)$value);if(isset($aliases[$key]))$candidate[$col]=$aliases[$key];}if(in_array('placa',$candidate,true)&&in_array('veiculo',$candidate,true)){$map=$candidate;continue;}if($row['line']>20)break;continue;}
    $data=[];$original=[];foreach($map as $col=>$field){$value=trim((string)($values[$col]??''));$original[$field]=$value;$data[$field]=$value;}
    if(empty($data['placa'])&&empty($data['veiculo']))continue;
    if(isset($data['data_evento'])){$data['data_original']=$data['data_evento'];if(!empty($sheet['excel'])&&preg_match('/^\d+(?:\.\d+)?$/D',$data['data_evento'])&&(float)$data['data_evento']>0&&(float)$data['data_evento']<100000){$origin=!empty($sheet['date1904'])?'1904-01-01':'1899-12-30';$data['data_evento']=(new DateTimeImmutable($origin))->modify('+'.(int)$data['data_evento'].' days')->format('Y-m-d');$data['data_original']=$data['data_evento'];}}
    try{$normalized=Records::normalize($data,true);$output[]=['sheet'=>$sheet['name'],'line'=>$row['line'],'data'=>$normalized,'original'=>$original,'system_id'=>preg_match('/^(?:FB-)?(\d+)$/D',(string)($data['system_id']??''),$m)?(int)$m[1]:null];}catch(InvalidArgumentException $e){$issues[]=['sheet'=>$sheet['name'],'line'=>$row['line'],'error'=>$e->getMessage()];}
   }}if(!$output&&!$issues)throw new InvalidArgumentException('Não encontrei as colunas PLACA e VEÍCULO/MARCA/MODELO ou registros preenchidos.');return ['rows'=>$output,'errors'=>$issues];
 }
 private static function header(string $v):string {return trim(preg_replace('/[^a-z0-9]+/',' ',Records::norm($v)));}
 public static function plan(PDO $db,array $parsed,string $fileHash):array {
  $existing=[];foreach($db->query('SELECT id,source_key,content_hash,revision FROM fb_occurrences') as $row){if($row['source_key'])$existing['source'][$row['source_key']]=true;$existing['hash'][$row['content_hash']]=true;$existing['ids'][(int)$row['id']]=(int)$row['revision'];}
  $duplicates=0;$skipped=0;$updates=0;foreach($parsed['rows'] as &$row){$row['source_key']=hash('sha256',$fileHash.'|'.$row['sheet'].'|'.$row['line']);$row['already']=isset($existing['source'][$row['source_key']]);$row['duplicate']=!$row['already']&&isset($existing['hash'][$row['data']['content_hash']]);$row['revision']=$row['system_id']?($existing['ids'][$row['system_id']]??null):null;if($row['system_id']&&$row['revision']===null)$row['invalid_id']=true;$duplicates+=(int)$row['duplicate'];$skipped+=(int)$row['already'];$updates+=(int)($row['system_id']&&$row['revision']!==null);}unset($row);
  return $parsed+['duplicates'=>$duplicates,'skipped'=>$skipped,'updates'=>$updates,'file_hash'=>$fileHash];
 }
 public static function commit(PDO $db,array $plan,int $user,string $name,bool $update=false,bool $allowDuplicates=false):array {
  if(!empty($plan['errors']))throw new InvalidArgumentException('Corrija as linhas inválidas e importe novamente.');
  if(count($plan['rows'])>20000)throw new InvalidArgumentException('Importação muito grande.');$db->beginTransaction();$counts=['inserted'=>0,'updated'=>0,'skipped'=>0];
  try{foreach($plan['rows'] as $row){if(!empty($row['invalid_id']))throw new InvalidArgumentException('A planilha contém um ID que não existe neste sistema. Remova o ID para cadastrar como novo.');
    if($row['system_id']){if(!$update){$counts['skipped']++;continue;}Records::save($db,$row['data'],$user,$row['system_id'],$row['revision'],'Atualização por planilha',true);$counts['updated']++;continue;}
    $q=$db->prepare('SELECT id FROM fb_occurrences WHERE source_key=?');$q->execute([$row['source_key']]);if($q->fetchColumn()||(!$allowDuplicates&&!empty($row['duplicate']))){$counts['skipped']++;continue;}
    Records::save($db,$row['data'],$user,null,null,'Importação',true,$row['source_key'],$row['original']);$counts['inserted']++;}
   $q=$db->prepare('INSERT INTO fb_imports(file_hash,filename,total,inserted,updated,skipped,user_id) VALUES(?,?,?,?,?,?,?)');$q->execute([$plan['file_hash'],basename($name),count($plan['rows']),$counts['inserted'],$counts['updated'],$counts['skipped'],$user]);$db->commit();return $counts;
  }catch(Throwable $e){$db->rollBack();throw $e;}
 }
 public static function export(array $records,string $format,string $path,bool $template=false):void {
  $headers=array_merge(Records::LABELS,['ID DO SISTEMA','ETAPA','OBSERVAÇÕES']);$rows=[$headers];if(!$template)foreach($records as $record){$line=[];foreach(Records::FIELDS as $field){$v=$record[$field]??'';if($field==='data_evento')$v=$v?date('d/m/Y',strtotime($v)):($record['data_original']??'');$line[]=$v;}$line[]=$record['protocolo'];$line[]=$record['etapa'];$line[]=$record['observacoes'];$rows[]=$line;}
  if($format==='csv'){$f=fopen($path,'wb');fwrite($f,"\xEF\xBB\xBF");foreach($rows as $line){$line=array_map(static fn($v)=>preg_match('/^[\s]*[=+@-]/u',(string)$v)?"'".$v:$v,$line);fputcsv($f,$line,';','"','');}fclose($f);return;}
  if(!class_exists('ZipArchive'))throw new RuntimeException('A extensão ZIP é necessária para exportar Excel. Use CSV.');$zip=new ZipArchive();if($zip->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Não foi possível criar o Excel.');
  $xml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="17" width="24" customWidth="1"/></cols><sheetData>';
  foreach($rows as $i=>$line){$n=$i+1;$xml.='<row r="'.$n.'">';foreach($line as $col=>$v){$letters='';for($c=$col+1;$c>0;$c=intdiv($c-1,26))$letters=chr(65+($c-1)%26).$letters;$v=mb_substr((string)$v,0,32000,'UTF-8');$v=preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/','',$v);$xml.='<c r="'.$letters.$n.'" t="inlineStr" s="'.($i===0?'1':'0').'"><is><t xml:space="preserve">'.htmlspecialchars($v,ENT_XML1|ENT_QUOTES,'UTF-8').'</t></is></c>';}$xml.='</row>';}$xml.='</sheetData><autoFilter ref="A1:Q'.count($rows).'"/></worksheet>';
  $zip->addFromString('xl/worksheets/sheet1.xml',$xml);$zip->addFromString('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>');
  $zip->addFromString('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
  $zip->addFromString('xl/workbook.xml','<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Ocorrencias" sheetId="1" r:id="rId1"/></sheets></workbook>');
  $zip->addFromString('xl/_rels/workbook.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');
  $zip->addFromString('xl/styles.xml','<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="2"><xf fontId="0" fillId="0" borderId="0" xfId="0"/><xf fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');$zip->close();
 }
